-- Dados FICTÍCIOS para desenvolvimento local (scripts/dev-db.mjs). Não é produção.






-- Disciplinas da turma + professor (Atribuições)


-- Uma grade por turma (vigência 2026/2): seg–sex, 5 aulas de 50 min e intervalo depois da 3ª.

SELECT g.id, d, s.ord, s.dur, s.st, s.en, s.typ, s.lbl
  FROM (VALUES ('70000000-0000-0000-0000-000000000001'::uuid), ('70000000-0000-0000-0000-000000000002'::uuid)) AS g(id)
 CROSS JOIN generate_series(1, 5) AS d
 CROSS JOIN (VALUES
   (1, 50, '07:00', '07:50', 'LESSON', NULL),
   (2, 50, '07:50', '08:40', 'LESSON', NULL),
   (3, 50, '08:40', '09:30', 'LESSON', NULL),
   (4, 20, '09:30', '09:50', 'BREAK', 'Intervalo'),
   (5, 50, '09:50', '10:40', 'LESSON', NULL),
   (6, 50, '10:40', '11:30', 'LESSON', NULL)
 ) AS s(ord, dur, st, en, typ, lbl);
